def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    document_patches = image_patch.find("document")
    table_patches = image_patch.find("table")

    if not document_patches or not table_patches:
        return image_patch

    table_depth = min(table.compute_depth() for table in table_patches)

    on_table = [doc for doc in document_patches if doc.compute_depth() < table_depth]

    if not on_table:
        return image_patch

    return max(on_table, key=lambda doc: doc.area)

