modern_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    infant_patches = image_patch.find("infant")
    remote_patches = image_patch.find("remote control")

    if not man_patches or not infant_patches or not remote_patches:
        return image_patch

    # Find the man and infant patches that are closest to each other
    closest_pair = None
    min_distance = float('inf')

    for man in man_patches:
        for infant in infant_patches:
            for remote in remote_patches:
                distance_sum = abs(man.horizontal_center - infant.horizontal_center) + \
                               abs(man.vertical_center - infant.vertical_center) + \
                               abs(infant.horizontal_center - remote.horizontal_center) + \
                               abs(infant.vertical_center - remote.vertical_center)
                if distance_sum < min_distance:
                    min_distance = distance_sum
                    closest_pair = (man, infant, remote)

    if closest_pair:
        man, infant, remote = closest_pair
        return man

