    half_height = (bench.upper - bench.lower) / 2

    left_half = ImagePatch(bench.cropped_image, bench.left, bench.lower, bench_center_x, bench.upper)
    right_half = ImagePatch(bench.cropped_image, bench_center_x, bench.lower, bench.right, bench.upper)

    if abs(woman_center_x - bench_center_x) < half_width:
        if woman_center_x < bench_center_x:
            return right_half
        else:
            return left_half
    elif abs(woman_center_y - bench_center_y) < half_height:
        if woman_center_y < bench_center_y:
            return ImagePatch(bench.cropped_image, bench.left, bench.lower, bench.right, bench_center_y)
        else:
            return ImagePatch(bench.cropped_image, bench.left, bench

